package com.overheadoverload;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(OverheadOverloadConfig.GROUP)
public interface OverheadOverloadConfig extends Config
{
	String GROUP = "overheadoverload";

	@ConfigSection(
		name = "Countdown",
		description = "When and how long the countdown to the brew cue is shown.",
		position = 0
	)
	String countdownSection = "countdownSection";

	@ConfigSection(
		name = "Appearance",
		description = "Colours, font size and positioning of the overhead text.",
		position = 1
	)
	String appearanceSection = "appearanceSection";

	@Range(min = 3, max = 24)
	@ConfigItem(
		keyName = "countdownLength",
		name = "Countdown length",
		description = "How many numbers to show before BREW. E.g. 3 shows '3 2 1 BREW', 5 shows '5 4 3 2 1 BREW'.",
		position = 0,
		section = countdownSection
	)
	default int countdownLength()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "showCountdownNumbers",
		name = "Show countdown numbers",
		description = "Show the ticking numbers leading up to BREW. Turn off to only show the BREW cue.",
		position = 2,
		section = countdownSection
	)
	default boolean showCountdownNumbers()
	{
		return true;
	}

	@ConfigItem(
		keyName = "brewText",
		name = "Brew text",
		description = "The text shown on the brew cue tick.",
		position = 3,
		section = countdownSection
	)
	default String brewText()
	{
		return "BREW";
	}

	@Alpha
	@ConfigItem(
		keyName = "countdownColor",
		name = "Countdown colour",
		description = "Colour of the ticking countdown numbers.",
		position = 0,
		section = appearanceSection
	)
	default Color countdownColor()
	{
		return Color.WHITE;
	}

	@Alpha
	@ConfigItem(
		keyName = "brewColor",
		name = "Brew colour",
		description = "Colour of the BREW cue text.",
		position = 1,
		section = appearanceSection
	)
	default Color brewColor()
	{
		return Color.GREEN;
	}

	@Range(min = 8, max = 60)
	@ConfigItem(
		keyName = "fontSize",
		name = "Font size",
		description = "Size of the overhead text.",
		position = 2,
		section = appearanceSection
	)
	default int fontSize()
	{
		return 16;
	}

	@ConfigItem(
		keyName = "boldFont",
		name = "Bold text",
		description = "Render the overhead text in bold.",
		position = 3,
		section = appearanceSection
	)
	default boolean boldFont()
	{
		return true;
	}

	@Range(min = -100, max = 200)
	@ConfigItem(
		keyName = "heightOffset",
		name = "Height offset",
		description = "Raises or lowers the text above your player. Higher values move it up.",
		position = 4,
		section = appearanceSection
	)
	default int heightOffset()
	{
		return 40;
	}
}

package com.overheadoverload;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.OverlayUtil;

public class OverheadOverloadOverlay extends Overlay
{
	/** The BREW cue lands this many ticks before the overload refresh. */
	private static final int BREW_OFFSET = 1;

	private final Client client;
	private final OverheadOverloadConfig config;
	private final OverheadOverloadPlugin plugin;

	@Inject
	private OverheadOverloadOverlay(Client client, OverheadOverloadConfig config, OverheadOverloadPlugin plugin)
	{
		this.client = client;
		this.config = config;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.UNDER_WIDGETS);
		setPriority(OverlayPriority.MED);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final int ticksUntilRefresh = plugin.getTicksUntilRefresh();
		if (ticksUntilRefresh < 0)
		{
			return null;
		}

		final String text;
		final Color color;

		if (ticksUntilRefresh == BREW_OFFSET)
		{
			// The brew cue tick: one tick before the overload refresh.
			text = config.brewText();
			color = config.brewColor();
		}
		else
		{
			final int number = ticksUntilRefresh - BREW_OFFSET;
			if (!config.showCountdownNumbers() || number < 1 || number > config.countdownLength())
			{
				return null;
			}
			text = String.valueOf(number);
			color = config.countdownColor();
		}

		final Player local = client.getLocalPlayer();
		if (local == null)
		{
			return null;
		}

		final LocalPoint localLocation = local.getLocalLocation();
		if (localLocation == null)
		{
			return null;
		}

		final int height = local.getLogicalHeight() + config.heightOffset();
		final Point anchor = Perspective.localToCanvas(client, localLocation, client.getPlane(), height);
		if (anchor == null)
		{
			return null;
		}

		final int style = config.boldFont() ? Font.BOLD : Font.PLAIN;
		graphics.setFont(new Font(FontManager.getRunescapeFont().getName(), style, config.fontSize()));

		// Centre the text horizontally over the player.
		final FontMetrics metrics = graphics.getFontMetrics();
		final Point textLocation = new Point(anchor.getX() - metrics.stringWidth(text) / 2, anchor.getY());
		OverlayUtil.renderTextLocation(graphics, textLocation, text, color);

		return null;
	}
}

package com.overheadoverload;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Overhead Overload",
	description = "Shows your Chambers of Xeric overload refresh timer as a countdown above your character.",
	tags = {"cox", "chambers", "xeric", "overload", "brew", "raid", "raids", "tick", "overhead"}
)
public class OverheadOverloadPlugin extends Plugin
{
	/**
	 * Varbit 5418 = COX_OVERLOAD_REFRESHES_REMAINING.
	 * Set to 20 when the Chambers of Xeric overload is drunk and decremented by 1 every
	 * {@link #TICKS_PER_REFRESH} ticks, exactly on the tick that your stats are restored.
	 */
	static final int COX_OVERLOAD_VARBIT = 5418;

	/** The overload re-boosts (and the varbit decrements) every 25 ticks = 15 seconds. */
	static final int TICKS_PER_REFRESH = 25;

	@Inject
	private Client client;

	@Inject
	private OverheadOverloadConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private OverheadOverloadOverlay overlay;

	/** True while a CoX overload is active. */
	private boolean active;

	/** Last seen value of the overload varbit, used to detect refresh ticks. */
	private int prevCycles;

	/** Ticks elapsed since the last refresh tick (0 on the refresh tick itself). */
	private int ticksSinceRefresh;

	/** Set on the refresh tick so the following GameTick doesn't count it twice. */
	private boolean justRefreshed;

	@Override
	protected void startUp()
	{
		reset();
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		reset();
	}

	@Provides
	OverheadOverloadConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OverheadOverloadConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();
		if (state == GameState.LOGGING_IN || state == GameState.HOPPING || state == GameState.LOGIN_SCREEN)
		{
			reset();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		final int val = client.getVarbitValue(COX_OVERLOAD_VARBIT);
		if (val == prevCycles)
		{
			return;
		}

		prevCycles = val;

		if (val > 0)
		{
			// The varbit changed to a positive value: either the overload was just drunk
			// (0 -> 20) or it ticked down by one (a stat refresh). Both happen on the tick
			// the boost is (re)applied, so re-sync the cycle to it.
			active = true;
			ticksSinceRefresh = 0;
			justRefreshed = true;
		}
		else
		{
			// Overload expired or we left the raid.
			active = false;
			justRefreshed = false;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!active)
		{
			return;
		}

		if (justRefreshed)
		{
			// This is the refresh tick; the varbit change already zeroed the counter.
			justRefreshed = false;
		}
		else
		{
			ticksSinceRefresh++;
		}
	}

	private void reset()
	{
		active = false;
		prevCycles = 0;
		ticksSinceRefresh = 0;
		justRefreshed = false;
	}

	boolean isActive()
	{
		return active;
	}

	/**
	 * Number of ticks until the next overload refresh, where 0 means the refresh is happening
	 * on this tick. Returns -1 when no overload is active.
	 */
	int getTicksUntilRefresh()
	{
		if (!active)
		{
			return -1;
		}

		final int into = ticksSinceRefresh % TICKS_PER_REFRESH;
		return (TICKS_PER_REFRESH - into) % TICKS_PER_REFRESH;
	}
}

package com.overheadoverload;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class OverheadOverloadPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(OverheadOverloadPlugin.class);
		RuneLite.main(args);
	}
}
